import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as i}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agentic Engineering Patterns（Simon Willison）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/agentic-engineering-patterns.md","filePath":"zh/tech/agent/agentic-engineering-patterns.md","lastUpdated":1780925467000}'),o={name:"zh/tech/agent/agentic-engineering-patterns.md"};function r(s,a,l,h,g,p){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="agentic-engineering-patterns-simon-willison" tabindex="-1">Agentic Engineering Patterns（Simon Willison） <a class="header-anchor" href="#agentic-engineering-patterns-simon-willison" aria-label="Permalink to &quot;Agentic Engineering Patterns（Simon Willison）&quot;">​</a></h1><blockquote><p>来源：Simon Willison 的 <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a> 系列指南</p></blockquote><h2 id="什么是-agentic-engineering" tabindex="-1">什么是 Agentic Engineering <a class="header-anchor" href="#什么是-agentic-engineering" aria-label="Permalink to &quot;什么是 Agentic Engineering&quot;">​</a></h2><p>用 LLMs + 系统化提示词 + 工具集成来解决问题的工程实践。</p><p>关键认识：<strong>AI 工具让写代码变得几乎免费，但交付好代码仍然很贵。</strong></p><hr><h2 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to &quot;原则&quot;">​</a></h2><h3 id="_1-代码现在很便宜-但好代码仍然有成本" tabindex="-1">1. 代码现在很便宜，但好代码仍然有成本 <a class="header-anchor" href="#_1-代码现在很便宜-但好代码仍然有成本" aria-label="Permalink to &quot;1. 代码现在很便宜，但好代码仍然有成本&quot;">​</a></h3><p>写新代码的成本急剧下降——但交付&quot;好代码&quot;仍然贵得多。</p><p>好代码的定义：</p><ul><li>代码能正常工作</li><li>我们知道代码能工作（有测试验证）</li><li>解决了正确的问题</li><li>处理错误情况，不只是 Happy Path</li><li>简洁最小，只做需要的事</li><li>有测试保护</li><li>有适当的文档且反映当前状态</li><li>设计有利于未来变更</li></ul><p>Coding Agent 能帮助实现大部分，但开发者仍要负责确保产出是好代码。</p><h3 id="_2-建立新习惯" tabindex="-1">2. 建立新习惯 <a class="header-anchor" href="#_2-建立新习惯" aria-label="Permalink to &quot;2. 建立新习惯&quot;">​</a></h3><p>每次本能反应说&quot;不值得做这个&quot;时，用异步 Agent session 试试——最坏情况是十分钟后发现确实不值得。</p><h3 id="_3-积累你知道怎么做的事" tabindex="-1">3. 积累你知道怎么做的事 <a class="header-anchor" href="#_3-积累你知道怎么做的事" aria-label="Permalink to &quot;3. 积累你知道怎么做的事&quot;">​</a></h3><p>软件开发的关键技能之一是知道什么可能、什么不可能，以及怎么做。</p><p>最佳实践是<strong>积累解决方案的运行示例</strong>，而不是只知道理论上的可能性。</p><p>积累方式：</p><ul><li>博客、TIL 文章</li><li>GitHub 仓库（大量小 PoC）</li><li>HTML tools（单文件页面解决特定问题）</li><li>Research repo（用 Agent 研究问题并产出工作代码+报告）</li></ul><p><strong>关键</strong>：Coding Agent 让这个积累习惯更有价值——如果一个技巧被记录在带工作代码示例的地方，Agent 可以查阅并在未来类似项目中复用。</p><h3 id="_4-从-hoard-中重组" tabindex="-1">4. 从 Hoard 中重组 <a class="header-anchor" href="#_4-从-hoard-中重组" aria-label="Permalink to &quot;4. 从 Hoard 中重组&quot;">​</a></h3><p>最喜欢的提示模式之一：让 Agent 通过组合两个或多个现有工作示例来构建新东西。</p><hr><h2 id="coding-agent-工作原理" tabindex="-1">Coding Agent 工作原理 <a class="header-anchor" href="#coding-agent-工作原理" aria-label="Permalink to &quot;Coding Agent 工作原理&quot;">​</a></h2><h3 id="核心组成" tabindex="-1">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to &quot;核心组成&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Coding Agent = LLM + System Prompt + Tools（循环）</span></span></code></pre></div><h3 id="llm-的本质" tabindex="-1">LLM 的本质 <a class="header-anchor" href="#llm-的本质" aria-label="Permalink to &quot;LLM 的本质&quot;">​</a></h3><p>LLM 是<strong>token 补全机器</strong>。输入文本（转为整数 token），输出下一个 token。</p><p>Token 很重要：因为 LLM 提供商按 token 收费，且上下文窗口有 token 数量限制。</p><h3 id="chat-模板" tabindex="-1">Chat 模板 <a class="header-anchor" href="#chat-模板" aria-label="Permalink to &quot;Chat 模板&quot;">​</a></h3><p>LLM 是无状态的，每次执行 prompt 都是从零开始。Chat 只是通过在每次用户输入时<strong>回放整个对话历史</strong>来模拟对话。</p><p>这意味着：对话越长，每次输入 prompt 的成本越高。</p><h3 id="token-缓存" tabindex="-1">Token 缓存 <a class="header-anchor" href="#token-缓存" aria-label="Permalink to &quot;Token 缓存&quot;">​</a></h3><p>大多数提供商对缓存的 token 有折扣。Coding Agent 尽量避免修改早期对话内容，以保证缓存被高效利用。</p><h3 id="调用工具" tabindex="-1">调用工具 <a class="header-anchor" href="#调用工具" aria-label="Permalink to &quot;调用工具&quot;">​</a></h3><p>工具是 Agent Harness 暴露给 LLM 的函数。机制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>System: 如果需要天气，结束本轮时输出 &lt;tool&gt;get_weather(city_name)&lt;/tool&gt;</span></span>
<span class="line"><span>User: 旧金山的天气如何？</span></span>
<span class="line"><span>Assistant: &lt;tool&gt;get_weather(&quot;San Francisco&quot;)&lt;/tool&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ Harness 执行工具，返回结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>User: &lt;tool-result&gt;61°, 多云&lt;/tool-result&gt;</span></span>
<span class="line"><span>Assistant: [根据结果回答]</span></span></code></pre></div><p>大多数 Coding Agent 定义十多个工具。最强大的是代码执行工具：<code>Bash()</code> 或 <code>Python()</code>。</p><h3 id="推理-reasoning" tabindex="-1">推理（Reasoning） <a class="header-anchor" href="#推理-reasoning" aria-label="Permalink to &quot;推理（Reasoning）&quot;">​</a></h3><p>2025 年的大进步：推理能力被引入前沿模型。模型在回答前先生成&quot;思考&quot;文本，花更多时间和 token 来解决问题。</p><p>推理对调试特别有用：让模型有机会追踪复杂代码路径，混合工具调用并用推理阶段追溯问题根源。</p><h3 id="system-prompt" tabindex="-1">System Prompt <a class="header-anchor" href="#system-prompt" aria-label="Permalink to &quot;System Prompt&quot;">​</a></h3><p>System Prompt 告诉模型它应该如何行为，可以有几百行。比如 <a href="https://github.com/openai/codex/blob/rust-v0.114.0/codex-rs/core/templates/model_instructions/gpt-5.2-codex_instructions_template.md" target="_blank" rel="noreferrer">OpenAI Codex 的 System Prompt</a>。</p><hr><h2 id="使用-git" tabindex="-1">使用 Git <a class="header-anchor" href="#使用-git" aria-label="Permalink to &quot;使用 Git&quot;">​</a></h2><h3 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h3><ul><li><strong>每次改一行</strong>：小提交更容易追溯和理解</li><li><strong>commit message 描述意图</strong>：不只是描述改了什么，还要说为什么</li><li><strong>atom commit</strong>：把相关的变更放一起</li></ul><h3 id="agent-友好的-commit" tabindex="-1">Agent 友好的 commit <a class="header-anchor" href="#agent-友好的-commit" aria-label="Permalink to &quot;Agent 友好的 commit&quot;">​</a></h3><p>Agent 适合用结构化的 commit message：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;: &lt;short description&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;body with details&gt;</span></span></code></pre></div><p>Agent 能生成高质量 commit message，前提是给清楚的结构指引。</p><hr><h2 id="subagents" tabindex="-1">Subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents&quot;">​</a></h2><h3 id="为什么需要-subagent" tabindex="-1">为什么需要 Subagent <a class="header-anchor" href="#为什么需要-subagent" aria-label="Permalink to &quot;为什么需要 Subagent&quot;">​</a></h3><p>LLM 受上下文限制（通常 100k-1M tokens，实际最佳效果在 200k 以下）。Subagent 提供了一种处理更大任务的方式，避免消耗主 Agent 宝贵的上下文。</p><p>当 Coding Agent 使用 Subagent 时，它有效地派遣自己的一个新副本带着全新的上下文窗口去完成指定目标。</p><h3 id="三种-subagent-类型" tabindex="-1">三种 Subagent 类型 <a class="header-anchor" href="#三种-subagent-类型" aria-label="Permalink to &quot;三种 Subagent 类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>用途</th></tr></thead><tbody><tr><td><strong>Explore Subagent</strong></td><td>主 Agent 暂停，Subagent 探索代码库后返回发现</td></tr><tr><td><strong>Parallel Subagent</strong></td><td>主 Agent 同时运行多个 Subagent（可选择更小更快的模型）</td></tr><tr><td><strong>Specialist Subagent</strong></td><td>定制 System Prompt 或工具，比如 Code Reviewer、Test Runner、Debugger</td></tr></tbody></table><h3 id="specialist-例子" tabindex="-1">Specialist 例子 <a class="header-anchor" href="#specialist-例子" aria-label="Permalink to &quot;Specialist 例子&quot;">​</a></h3><ul><li><strong>Code Reviewer</strong>：专门审查代码找 bug 和设计问题</li><li><strong>Test Runner</strong>：隐藏完整测试输出，只报告失败详情</li><li><strong>Debugger</strong>：专门调试，用 token 推理代码库并运行代码片断来隔离问题</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>Subagent 不需要滥用。最有价值的地方是保留主上下文并管理 token 密集操作。Root Agent 完全有能力调试或审查自己的输出——前提是有足够 token。</p><hr><h2 id="测试与-qa" tabindex="-1">测试与 QA <a class="header-anchor" href="#测试与-qa" aria-label="Permalink to &quot;测试与 QA&quot;">​</a></h2><h3 id="红绿-tdd" tabindex="-1">红绿 TDD <a class="header-anchor" href="#红绿-tdd" aria-label="Permalink to &quot;红绿 TDD&quot;">​</a></h3><p>&quot;使用红/绿 TDD&quot; 是一个简洁有效的获得更好 Agent 结果的方法。</p><p><strong>Red/Green TDD</strong>：</p><ul><li><strong>Red</strong>：先写测试，确认测试失败</li><li><strong>Green</strong>：实现代码让测试通过</li></ul><p>这对 Agent 特别有价值：测试先行的开发方式防止 Agent 写出不工作或不必要的代码，同时建立回归测试套件保护未来变更。</p><h3 id="agentic-手动测试" tabindex="-1">Agentic 手动测试 <a class="header-anchor" href="#agentic-手动测试" aria-label="Permalink to &quot;Agentic 手动测试&quot;">​</a></h3><p>Coding Agent 可以做自动化测试，但无法取代真实的手动测试。用 Agent 做手动测试：</p><ol><li>让 Agent 写测试脚本</li><li>让 Agent 做探索性测试</li><li>让 Agent 捕获截图和日志</li></ol><hr><h2 id="理解代码" tabindex="-1">理解代码 <a class="header-anchor" href="#理解代码" aria-label="Permalink to &quot;理解代码&quot;">​</a></h2><h3 id="linear-walkthroughs" tabindex="-1">Linear Walkthroughs <a class="header-anchor" href="#linear-walkthroughs" aria-label="Permalink to &quot;Linear Walkthroughs&quot;">​</a></h3><p>让 Agent 一行一行遍历代码，在每个关键决策点停下来解释。</p><p>工具如 <a href="https://github.com/simonw/showboat" target="_blank" rel="noreferrer">Showboat</a> 可以让 Agent 在代码中导航时做笔记。</p><h3 id="interactive-explanations" tabindex="-1">Interactive Explanations <a class="header-anchor" href="#interactive-explanations" aria-label="Permalink to &quot;Interactive Explanations&quot;">​</a></h3><p>用对话方式理解代码，让 Agent 回答关于代码库的问题。</p><hr><h2 id="annotated-prompts" tabindex="-1">Annotated Prompts <a class="header-anchor" href="#annotated-prompts" aria-label="Permalink to &quot;Annotated Prompts&quot;">​</a></h2><h3 id="渐进式改进" tabindex="-1">渐进式改进 <a class="header-anchor" href="#渐进式改进" aria-label="Permalink to &quot;渐进式改进&quot;">​</a></h3><p>好的做法是：</p><ol><li>先用简单提示启动 Agent</li><li>看它怎么失败</li><li>针对性改进提示</li><li>重复</li></ol><p>示例：GIF 优化工具的提示迭代过程，展示了如何通过后续提示逐步改进。</p><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Agentic Engineering 的关键在于：</p><ol><li><strong>接受代码便宜、好代码贵</strong>的现实</li><li><strong>积累可复用的工作示例</strong></li><li><strong>理解 Agent 机制</strong>（LLM + System Prompt + Tools 循环）</li><li><strong>善用 Subagent</strong> 保持上下文干净</li><li><strong>红/绿 TDD</strong> 保护代码质量</li><li><strong>持续迭代提示</strong> 而非一次性完美</li></ol>`,89)])])}const q=t(o,[["render",r]]);export{m as __pageData,q as default};
